import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CjAa9jTu.js";const m=JSON.parse('{"title":"Comunicación SPI","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/44_spi.md","filePath":"py32f003-getting-started/44_spi.md"}'),i={name:"py32f003-getting-started/44_spi.md"};function n(s,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="comunicacion-spi" tabindex="-1">Comunicación SPI <a class="header-anchor" href="#comunicacion-spi" aria-label="Permalink to &quot;Comunicación SPI&quot;">​</a></h1><h2 id="concepto" tabindex="-1">Concepto <a class="header-anchor" href="#concepto" aria-label="Permalink to &quot;Concepto&quot;">​</a></h2><p>SPI transmite datos mediante un reloj y señales separadas de envío y recepción. El controlador activa la selección <strong>CS</strong> del dispositivo con el que quiere comunicarse.</p><table tabindex="0"><thead><tr><th>Señal</th><th>Función</th><th>Referencia en la placa</th></tr></thead><tbody><tr><td>SCK</td><td>Reloj del controlador</td><td>PA1</td></tr><tr><td>MOSI</td><td>Datos del controlador al periférico</td><td>PB5</td></tr><tr><td>MISO</td><td>Datos del periférico al controlador</td><td>PA0</td></tr><tr><td>CS</td><td>Selección del periférico</td><td>PA2</td></tr><tr><td>VCC y GND</td><td>Alimentación y referencia</td><td>Según la tensión del montaje</td></tr></tbody></table><h2 id="recursos-compartidos" tabindex="-1">Recursos compartidos <a class="header-anchor" href="#recursos-compartidos" aria-label="Permalink to &quot;Recursos compartidos&quot;">​</a></h2><ul><li><strong>PB5</strong> también controla el LED integrado.</li><li><strong>PA0 y PA1</strong> se utilizan para <code>Serial</code> en las prácticas UART.</li><li><strong>PA2</strong> se utiliza como entrada digital o ADC en otros ejercicios.</li></ul><p>Para preparar un ejemplo SPI hay que liberar esas funciones y configurar los pines adecuados. Los pines SPI genéricos del paquete Arduino 0.1.7 (PA4, PA5, PA6 y PA7) no coinciden con este encapsulado.</p><h2 id="antes-de-conectar-un-dispositivo" tabindex="-1">Antes de conectar un dispositivo <a class="header-anchor" href="#antes-de-conectar-un-dispositivo" aria-label="Permalink to &quot;Antes de conectar un dispositivo&quot;">​</a></h2><p>Consulta su tensión de alimentación, niveles lógicos, modo SPI, frecuencia máxima, orden de bits y protocolo. Verifica la correspondencia del conector de seis pines en el <a href="./03_pinout">pinout</a> y el <a href="/unit_devlab_cortex_m_examples/py32f003/esquematico.pdf">esquemático</a>.</p><p>Las pantallas y memorias pueden requerir búferes considerables para los <strong>2 KB de RAM</strong> de esta variante. Revisa el uso de memoria al compilar antes de añadir una biblioteca. Esta sección es una referencia para ampliar el taller; las primeras prácticas se encuentran en <a href="./../examples/">Laboratorios</a>.</p>',10)])])}const h=a(i,[["render",n]]);export{m as __pageData,h as default};
